<?php

namespace Database\Seeders;

use App\Models\HousingUnit;
use Illuminate\Database\Seeder;

/**
 * The 10 houses of the campus town. Each unit is linked to its assets by model_key
 * (front/public/assets/houses/<model_key>/) and positioned at the door interaction point.
 *
 * Positions come from front/public/assets/town/town.layout.json ("door"), generated by
 * map-src/CampusCove/build_town.py — regenerate both together if the town layout changes.
 */
class HousingUnitSeeder extends Seeder
{
    /** @var list<array{0:string,1:string,2:int,3:float,4:float,5:float,6:string}> key, offer, price, x, y, z, colour */
    private const HOUSES = [
        ['house_01', 'buy', 2400, 9.023, 1.25, 27.771, '#E8E4DA'],     // Maple Cottage
        ['house_02', 'buy', 2400, 23.623, 1.25, 17.163, '#78A0C4'],   // Bluebell Bungalow
        ['house_03', 'buy', 2500, 29.2, 1.25, 0.0, '#E8C878'],        // Sunny Nook
        ['house_04', 'buy', 2900, 23.623, 1.25, -17.163, '#96C8AA'],  // Mint Villa
        ['house_05', 'buy', 4200, 9.023, 1.25, -27.771, '#9C4834'],   // Brick Townhouse
        ['house_06', 'buy', 2600, -9.023, 1.25, -27.771, '#D69696'],  // Rose Cottage
        ['house_07', 'buy', 3100, -23.623, 1.25, -17.163, '#CE7858'], // Terracotta Casa
        ['house_08', 'buy', 4800, -29.2, 1.25, 0.0, '#F0F0EE'],       // Modern Cube
        ['house_09', 'buy', 5200, -23.623, 1.25, 17.163, '#3A3C48'],  // Neon Loft
        ['house_10', 'buy', 3400, -9.023, 1.25, 27.771, '#8A5A3A'],   // Forest Lodge
    ];

    /** @var array<string, array{minX:float,maxX:float,minZ:float,maxZ:float,maxY?:float}> */
    private const INTERIOR_BOUNDS = [
        'house_01' => ['minX' => -6.395, 'maxX' => 6.395, 'minZ' => -5.0, 'maxZ' => 5.2],
        'house_02' => ['minX' => -6.595, 'maxX' => 6.595, 'minZ' => -4.6, 'maxZ' => 5.2],
        'house_03' => ['minX' => -6.195, 'maxX' => 6.195, 'minZ' => -5.4, 'maxZ' => 5.2],
        'house_04' => ['minX' => -6.795, 'maxX' => 6.795, 'minZ' => -5.6, 'maxZ' => 5.2],
        'house_05' => ['minX' => -5.795, 'maxX' => 5.795, 'minZ' => -4.6, 'maxZ' => 5.2, 'maxY' => 5.6],
        'house_06' => ['minX' => -6.495, 'maxX' => 6.495, 'minZ' => -5.2, 'maxZ' => 5.2],
        'house_07' => ['minX' => -6.795, 'maxX' => 6.795, 'minZ' => -6.0, 'maxZ' => 5.2],
        'house_08' => ['minX' => -6.295, 'maxX' => 6.295, 'minZ' => -5.0, 'maxZ' => 5.2, 'maxY' => 5.6],
        'house_09' => ['minX' => -6.295, 'maxX' => 6.295, 'minZ' => -5.2, 'maxZ' => 5.2, 'maxY' => 5.6],
        'house_10' => ['minX' => -6.795, 'maxX' => 6.795, 'minZ' => -6.4, 'maxZ' => 5.2],
    ];

    public function run(): void
    {
        // Legacy MVP cubes (no model_key) are replaced by the houses; occupied ones are left alone.
        HousingUnit::query()->whereNull('model_key')->where('status', 'vacant')->delete();

        foreach (self::HOUSES as [$key, $offer, $price, $x, $y, $z, $color]) {
            $unit = HousingUnit::query()->firstOrNew(['model_key' => $key]);
            $unit->fill([
                'offer_type' => $offer,
                'price_coins' => $price,
                'rent_duration_hours' => 168,
                'pos_x' => $x,
                'pos_y' => $y,
                'pos_z' => $z,
                'size' => 2.5,
                'base_color_hex' => $color,
                'interior_bounds' => self::INTERIOR_BOUNDS[$key],
            ]);
            if (! $unit->exists) {
                $unit->status = 'vacant';
            }
            $unit->save();
        }
    }
}
